import {photos} from './photos.js';
import {laws,stations,sources,getSaved} from './data.js';
import {createPanorama} from './panorama.js?v=2';
const $=s=>document.querySelector(s);
const paths={school:'M3 21h18M5 21V9l7-6 7 6v12M9 21v-7h6v7M3 10l9-8 9 8M8 10h.01M16 10h.01',help:'M9.1 9a3 3 0 0 1 5.8 1c0 2-3 3-3 3m.1 4h.01|circle:12,12,9',expand:'M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5',map:'M3 6l6-3 6 3 6-3v15l-6 3-6-3-6 3V6m6-3v15m6-12v15',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z|circle:12,10,2.5',door:'M4 21h16M6 21V3h12v18M10 3v18m5-9h.01',play:'M9 6l9 6-9 6V6Z|circle:12,12,10',drag:'M8 13V7a2 2 0 0 1 4 0v5m0-2a2 2 0 0 1 4 0v3m0-2a2 2 0 0 1 4 0v5c0 4-2 6-6 6h-1c-2 0-3-1-4-2l-5-6a2 2 0 0 1 3-2l3 3',left:'m14 6-6 6 6 6',right:'m10 6 6 6-6 6',minus:'M5 12h14',plus:'M5 12h14m-7-7v14',book:'M12 5c-3-2-6-2-10-1v15c4-1 7-1 10 1m0-15c3-2 6-2 10-1v15c-4-1-7-1-10 1V5Z',close:'m6 6 12 12M6 18 18 6',landmark:'m3 9 9-6 9 6H3Zm2 3v7m5-7v7m4-7v7m5-7v7M2 22h20M3 19h18',handshake:'m2 12 4-8h4l2 2 2-2h4l4 8-5 6-3 2-3-1-6-5m3-6 4 2 3-3 4 3m-9 4 5 4m-2-7 6 5',shield:'M12 3 3 7v5c0 5 9 10 9 10s9-5 9-10V7l-9-4Zm-4 9 3 3 5-6',building:'M4 22V3h16v19M1 22h22M8 7h1m6 0h1M8 11h1m6 0h1M8 15h1m6 0h1m-6 7v-4h4v4',briefcase:'M8 7V4h8v3M3 7h18v14H3V7Zm0 6h18m-11-2v4h4v-4',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.9M16 3.1a4 4 0 0 1 0 7.8|circle:9,7,4',leaf:'M21 3C12 1 2 6 4 15s17 8 17-12ZM3 22 16 9',wallet:'M20 7V4H4a2 2 0 0 0 0 4h18v13H4a2 2 0 0 1-2-2V6m20 6h-6v5h6m-3-2.5h.01',phone:'M7 2h10a2 2 0 0 1 2 2v16a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2Zm3 3h4m-3 14h2',award:'m8 14-2 8 6-3 6 3-2-8|circle:12,9,7',check:'m5 12 4 4L20 5',mouse:'M12 3a6 6 0 0 0-6 6v6a6 6 0 0 0 12 0V9a6 6 0 0 0-6-6Zm0 0v7'};
function icon(name){return `<svg viewBox="0 0 24 24" aria-hidden="true">${(paths[name]||paths.book).split('|').map(s=>s.startsWith('circle:')?(()=>{const[cx,cy,r]=s.slice(7).split(',');return `<circle cx="${cx}" cy="${cy}" r="${r}"/>`})():`<path d="${s}"/>`).join('')}</svg>`}
function icons(){document.querySelectorAll('[data-icon]').forEach(e=>{e.innerHTML=icon(e.dataset.icon);e.removeAttribute('data-icon')})}
icons();
let state=getSaved(localStorage),world,currentStation=-1,lawIndex=0,modalKind='',feedback=null,questionIndex=0;
function save(){try{localStorage.setItem('quqyq-360-v1',JSON.stringify(state))}catch{toast('Бұл құрылғыда прогресті сақтау қолжетімсіз. Квестті жалғастыра бер.')}}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),4000)}
function nextStation(){return stations.findIndex((s,i)=>!state.completed.includes(i))}
function updateProgress(){const n=state.completed.length;$('#enter').innerHTML=icon('door')+(n?'Саяхатты жалғастыру':'Мектепке кіру');$('#enter').onclick=()=>n?(n===6?celebrate():goStation(nextStation())):enter();$('#progressText').textContent=`${n} / 6`;$('#progressFill').style.width=n/6*100+'%';$('#journeyHint').textContent=n===6?'Жарайсың! Барлық бекет аяқталды.':currentStation<0?'Теориядан тәжірибеге — бір қадам':`${currentStation+1}-бекет: ${stations[currentStation].title}`;$('#journeyDots').innerHTML=stations.map((s,i)=>`<button aria-label="${i+1}-бекет: ${s.room}${state.completed.includes(i)?', аяқталды':''}" class="${state.completed.includes(i)?'done':currentStation===i?'current':''}" data-station="${i}">${state.completed.includes(i)?'✓':i+1}</button>`).join('');$('#journeyDots').querySelectorAll('button').forEach(b=>b.onclick=()=>goStation(+b.dataset.station))}
const modal=$('#modal');let previousFocus;
function openModal(kind,html){if(!modal.open){previousFocus=document.activeElement;modal.showModal()}modalKind=kind;$('#modalContent').innerHTML=html;icons();modal.scrollTop=0;$('#closeModal').focus({preventScroll:true})}
function closeModal(){modal.close();modalKind='';previousFocus?.focus?.({preventScroll:true})}
$('#closeModal').onclick=closeModal;modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});modal.addEventListener('cancel',()=>{modalKind='';previousFocus?.focus?.({preventScroll:true})});
function changeScene(name){world.setScene(name);icons();$('#intro').hidden=name!=='exterior';$('#sceneCard').hidden=name==='exterior';$('#locationName').textContent=name==='exterior'?'Мектеп алды':name==='lobby'?'Мектеп фойесі':stations[currentStation]?.room||'Мектеп';if(name==='exterior'){currentStation=-1}else if(name==='lobby'){currentStation=-1;$('#sceneLabel').textContent='ТАНЫСУ КЕҢІСТІГІ';$('#sceneTitle').textContent='Құқық әлеміне алғашқы қадам';$('#sceneDescription').textContent='Алдыңдағы стендтен құқықтың 9 саласын зертте. Содан кейін мектептегі квестке аттан.';$('#sceneAction').innerHTML=icon('book')+'Стендті зерттеу';$('#sceneAction').onclick=()=>showLaws(0)}else{const s=stations[currentStation];$('#sceneLabel').textContent=`${currentStation+1}-БЕКЕТ · ${s.room.toLocaleUpperCase('kk')}`;$('#sceneTitle').textContent=s.title;$('#sceneDescription').textContent=s.scenario;$('#sceneAction').innerHTML=icon(state.completed.includes(currentStation)?'check':'play')+(state.completed.includes(currentStation)?'Бекет қорытындысы':'Жағдаятты шешу');$('#sceneAction').onclick=()=>beginQuest(currentStation)}updateProgress()}
function enter(){closeModal();changeScene('lobby')}
$('#enter').onclick=enter;$('#home').onclick=()=>{closeModal();changeScene('exterior')};
function help(){openModal('help',`<div class="modal-pad"><h2>Мектепті зертте.<br>Шешіміңді таңда.</h2><p>Құқықты күнделікті өмірдегі жағдаяттар арқылы үйрен.</p><div class="help-grid"><div>${icon('drag')}<h3>Айналаңа қара</h3><p>Телефонда саусағыңмен, ноутбукте тінтуірмен сүйре. Пернетақтадағы бағыттау пернелері де жұмыс істейді.</p></div><div>${icon('book')}<h3>Теориямен таныс</h3><p>Мектепке кіріп, стендтегі 9 құқық саласын оқы. Әрқайсысында анықтама, баптар мен мысал бар.</p></div><div>${icon('shield')}<h3>Квесттен өт</h3><p>6 бекетті ретімен арала. Әр бекетте 3 сұраққа жауап беріп, түсіндірмені оқы. Қате жауапты түзете аласың.</p></div></div><p class="muted">Прогресс осы браузерде сақталады. Үзілістен кейін сол құрылғыда жалғастыра аласың.</p><button class="primary" id="helpDone">Түсінікті, бастайық</button></div>`);$('#helpDone').onclick=()=>{closeModal();if(world.current==='exterior')enter()}}
$('#help').onclick=help;$('#how').onclick=help;
function showLaws(index=0){lawIndex=index;if(!state.read.includes(index)){state.read.push(index);save()}const law=laws[index];openModal('laws',`<div class="law-layout"><aside class="law-nav"><h2>Құқықтың 9 саласы<small>Заңдар мен нақты баптар</small></h2><div class="law-tabs" role="tablist" aria-label="Құқық салалары">${laws.map((l,i)=>`<button class="law-tab" id="lawTab${i}" role="tab" aria-controls="lawPanel" aria-selected="${i===index}" data-law="${i}">${icon(l.icon)}${l.name}</button>`).join('')}</div></aside><article class="law-detail" id="lawPanel" role="tabpanel" aria-labelledby="lawTab${index}"><div class="law-symbol">${icon(law.icon)}</div><h2>${law.name}</h2><p>${law.definition}</p><h3>Заңдық негізі</h3><p>${law.basis}</p><h3>Нақты баптар мен нормалар</h3><ul>${law.articles.map(a=>`<li>${a}</li>`).join('')}</ul>${law.note?`<p class="muted">${law.note}</p>`:''}<div class="example"><strong>Өмірден мысал</strong><br>${law.example}</div><a class="source-link" href="${sources[law.source].url}" target="_blank" rel="noopener">Әділет: ресми мәтінді оқу</a>${index===8?`<br><a class="source-link" href="${sources[9].url}" target="_blank" rel="noopener">Салық кодексін оқу</a>`:''}<div class="law-bottom"><button class="primary" id="lawNext">${index<8?'Келесі құқық саласы':'Квестті бастау'}</button><button class="secondary" id="lawStart">${index<8?'Квестке өту': 'Стендке оралу'}</button></div><p class="muted">Оқылғаны: ${state.read.length} / 9</p></article></div>`);document.querySelectorAll('[data-law]').forEach(b=>b.onclick=()=>showLaws(+b.dataset.law));$('#lawNext').onclick=()=>index<8?showLaws(index+1):startQuest();$('#lawStart').onclick=()=>index<8?startQuest():closeModal();$('#lawTab'+index)?.scrollIntoView({block:'nearest',inline:'nearest'})}
function startQuest(){closeModal();const i=nextStation();if(i<0)celebrate();else goStation(i)}
function goStation(i){if(!world)return;const first=nextStation();if(first>=0&&i>first&&!state.completed.includes(i)){toast('Алдымен алдыңғы бекеттерді аяқта. Келесі бекет: '+(first+1));return}closeModal();currentStation=i;changeScene(stations[i].scene)}
function showMap(){const first=nextStation();openModal('map',`<div class="modal-pad"><h2>Мектеп картасы</h2><p>Теориямен танысып, бекеттерді ретімен аяқта.</p><div class="map-list"><button class="map-item" id="mapOutside">${icon('school')}<span><strong>Мектеп алды</strong><small>Саяхаттың басталуы</small></span></button><button class="map-item" id="mapLobby">${icon('book')}<span><strong>Мектеп фойесі</strong><small>Құқықтың 9 саласы</small></span></button>${stations.map((s,i)=>{const done=state.completed.includes(i),locked=first>=0&&i>first&&!done;return `<button class="map-item" data-map="${i}" ${locked?'disabled':''}>${icon(done?'check':s.icon)}<span><strong>${i+1}. ${s.room}</strong><small>${done?'Аяқталды':locked?'Алдыңғы бекеттен кейін ашылады':s.title}</small></span></button>`}).join('')}</div>${state.completed.length===6?'<button class="primary" id="showResult">Нәтижені көру</button>':''}<p class="muted">Әр бекетте 3 сұрақ. Қате жауап болса, түсіндірмені оқып, қайта таңда.</p></div>`);$('#mapOutside').onclick=()=>{closeModal();changeScene('exterior')};$('#mapLobby').onclick=enter;document.querySelectorAll('[data-map]').forEach(b=>b.onclick=()=>goStation(+b.dataset.map));if($('#showResult'))$('#showResult').onclick=celebrate}
$('#mapToggle').onclick=showMap;
function beginQuest(i){if(state.completed.includes(i)){stationDone(i);return}questionIndex=stations[i].questions.findIndex((q,j)=>!state.answers[`${i}-${j}`]?.done);if(questionIndex<0){stationDone(i);return}feedback=null;renderQuestion()}
function scenarioContext(i,text){const photo=photos[i];return `<div class="scenario-context"><figure class="scenario-photo"><img src="${photo.src}" alt="${photo.alt}" width="1400" height="933" decoding="async"><span class="photo-note">Көрнекі фото</span></figure><div class="scenario">${text}</div></div>`}
function renderQuestion(){const i=currentStation,s=stations[i],q=s.questions[questionIndex],key=`${i}-${questionIndex}`,answer=state.answers[key];openModal('quest',`<div class="modal-pad"><div class="quest-heading"><span class="badge">${i+1}-бекет · ${s.room}</span><span>${questionIndex+1} / 3 сұрақ</span></div><h2>${s.title}</h2>${scenarioContext(i,s.scenario)}<h3 class="question">${q.q}</h3><div class="answers">${q.options.map((o,j)=>`<button class="answer ${feedback?.choice===j?(feedback.correct?'correct':'wrong'):''}" data-answer="${j}" ${feedback?'disabled':''}><span class="letter">${['A','B','C'][j]}</span><span>${o}</span></button>`).join('')}</div><div aria-live="polite">${feedback?`<div class="feedback ${feedback.correct?'':'wrong'}"><strong>${feedback.correct?'Дұрыс жауап!':'Ойланып, қайта байқап көр.'}</strong><p>${feedback.correct?q.why:'Бұл жауап жағдаятты дұрыс шешпейді. '+(questionIndex===0?'Оқиғаның мәніне және кімнің құқығы қорғалатынына назар аудар.':'Құқықты құрметтейтін әрі заңға сай әрекетті таңда.')}</p></div>`:''}</div><div class="quest-bottom"><span class="muted">${feedback?.correct?'Түсіндірмені оқып, жалғастыр.':'Бір дұрыс жауапты таңда.'}</span>${feedback?`<button class="primary" id="nextQuestion">${feedback.correct?(questionIndex===2?'Бекетті аяқтау':'Келесі сұрақ'):'Қайта таңдау'}</button>`:''}</div></div>`);document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{const choice=+b.dataset.answer,correct=choice===q.correct;const prior=state.answers[key];state.answers[key]={choice,firstCorrect:prior?prior.firstCorrect:correct,done:correct};save();feedback={choice,correct};renderQuestion();$('#nextQuestion').focus({preventScroll:true})});if($('#nextQuestion'))$('#nextQuestion').onclick=()=>{if(!feedback.correct){feedback=null;renderQuestion();document.querySelector('[data-answer]')?.focus({preventScroll:true});return}if(questionIndex===2){if(!state.completed.includes(i))state.completed.push(i);save();updateProgress();stationDone(i)}else{questionIndex++;feedback=null;renderQuestion()}}}
function stationDone(i){const s=stations[i];if(!state.completed.includes(i)&&s.questions.every((_,j)=>state.answers[`${i}-${j}`]?.done)){state.completed.push(i);save();updateProgress()}openModal('done',`<div class="modal-pad"><div class="quest-heading"><span class="badge">${i+1}-бекет аяқталды</span>${icon('check')}</div><h2>Жарайсың! Шешім табылды.</h2>${scenarioContext(i,s.summary)}${s.questions.map((q,j)=>`<div class="review-row"><strong>${j+1}. ${q.q}</strong><p>${q.why}</p></div>`).join('')}<h3>Заңдық негіздер</h3>${s.refs.map(r=>`<a class="source-link" href="${sources[r].url}" target="_blank" rel="noopener">${sources[r].name}</a><br>`).join('')}<div class="quest-bottom"><button class="secondary" id="doneMap">Мектеп картасы</button><button class="primary" id="doneNext">${state.completed.length===6?'Нәтижені көру':'Келесі бекетке өту'}</button></div></div>`);$('#doneMap').onclick=showMap;$('#doneNext').onclick=()=>state.completed.length===6?celebrate():goStation(nextStation());$('#sceneAction').innerHTML=icon('check')+'Бекет қорытындысы'}
function celebrate(){let score=Object.values(state.answers).filter(a=>a.done&&a.firstCorrect).length;score=Math.min(score,18);openModal('complete',`<div class="celebration"><div class="award">${icon('award')}</div><h2>Құттықтаймыз,<br>құқық білгірі!</h2><p>Сен мектептегі барлық бекеттен өттің.<br>Енді өз құқығыңды қорғап, өзгенің құқығын құрметтеуге бір қадам жақынсың.</p><div class="result-stats"><div><b>6 / 6</b><span>бекет аяқталды</span></div><div><b>${score} / 18</b><span>алғашқы талпыныста</span></div></div><label for="studentName">Сертификатқа атыңды жаз</label><input id="studentName" maxlength="70" autocomplete="name" placeholder="Аты-жөнің"><p class="small">Атың тек сертификатқа қолданылады және серверге жіберілмейді.</p><div class="law-bottom"><button class="primary" id="printCertificate">${icon('award')}Сертификатты сақтау</button><button class="secondary" id="resultMap">Бекеттерді қайталау</button></div><button class="restart-button" id="resetQuest">Квестті қайта бастау</button><p class="muted" id="resetWarning" hidden>Прогресс өшіріледі. <button class="secondary" id="confirmReset">Иә, қайта бастау</button></p></div>`);$('#printCertificate').onclick=()=>printCertificate(score);$('#resultMap').onclick=showMap;$('#resetQuest').onclick=()=>{$('#resetWarning').hidden=false};$('#confirmReset').onclick=()=>{state={completed:[],answers:{},read:[]};save();closeModal();changeScene('exterior')};}
function printCertificate(score){let name=$('#studentName').value.trim();if(!name){$('#studentName').focus();toast('Сертификатқа атыңды жаз.');return}document.querySelector('.certificate')?.remove();const el=document.createElement('article');el.className='certificate';const title=document.createElement('h1');title.textContent='ҚАТЫСУ СЕРТИФИКАТЫ';const n=document.createElement('h2');n.textContent=name;el.append(title,n);for(const text of['«Құқықтық мектеп кеңістігі: теориядан тәжірибеге»','360° білім беру квестінің барлық 6 бекетін аяқтап, құқықтық білімін тәжірибеде қолданды.',`Алғашқы талпыныста дұрыс жауаптар: ${score} / 18.`,new Date().toLocaleDateString('kk-KZ',{year:'numeric',month:'long',day:'numeric',timeZone:'Asia/Almaty'}),'Оқу квестіне қатысқаны туралы.']){const p=document.createElement('p');p.textContent=text;el.append(p)}document.body.append(el);window.print()}
function showSources(){openModal('sources',`<div class="modal-pad"><h2>Заңдық дереккөздер</h2><p>ҚР заңнамасының «Әділет» ақпараттық-құқықтық жүйесіндегі ресми мәтіндері.</p>${sources.map(s=>`<div class="source-row"><a href="${s.url}" target="_blank" rel="noopener">${s.name}</a><p>${s.note}</p></div>`).join('')}<h3>Фотосуреттер</h3><p class="muted">Фотолар жағдаяттарды түсіндіруге арналған көрнекілік ретінде берілген. Оқу жағдаяттары суреттегі адамдарға қатысты нақты оқиғалар емес.</p>${photos.map((p,i)=>`<div class="source-row"><a href="${p.url}" target="_blank" rel="noopener">${i+1}-бекет · ${p.author} / Pexels</a></div>`).join('')}<a class="source-link" href="https://www.pexels.com/license/" target="_blank" rel="noopener">Pexels лицензиясы</a><h3>Мазмұндағы нақтылаулар</h3><p class="muted">Буллингке 127-2-бап сілтемесі берілді. Мектеп тәртібі мен телефонға қатысты жағдайлар «Білім туралы» заңның 47-бабымен байланыстырылды. Педагог құқығы үшін «Педагог мәртебесі туралы» заңның 6–7-баптары қолданылды. Ауланы ластауға қатысты 434-2-бап — Экология кодексінде емес, ӘҚБтК-де. Қаржы құқығында жаңа кодекстерге сілтемелер берілді.</p><p class="muted">Оқу жағдаяттары ықшамдалып түсіндірілген. Жауаптылық әрекетке, жасқа және нақты мән-жайға қарай анықталады; айыппұл автоматты түрде тағайындалмайды.</p></div>`)}$('#sources').onclick=showSources;
$('#fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else toast('Бұл браузерде толық экран батырмасы қолдау таппайды.')}catch{toast('Толық экранды ашу мүмкін болмады. Браузер баптауын тексер.')}};
$('#turnLeft').onclick=()=>world?.turn(1);$('#turnRight').onclick=()=>world?.turn(-1);$('#zoomIn').onclick=()=>world?.zoom(-1);$('#zoomOut').onclick=()=>world?.zoom(1);
try{world=await createPanorama(action=>{if(action==='enter')enter();else if(action==='laws')showLaws(0);else if(action==='start')startQuest();else if(action==='quest')beginQuest(currentStation);else if(action==='map')showMap();else if(action==='imageerror')toast('Панорама жүктелмеді. Интернетті тексеріп, локацияны қайта аш.');else if(action==='contextlost')toast('3D көрініс тоқтады. Бетті жаңартып көр. Прогрессің сақталған.')});changeScene('exterior');$('#loading').style.opacity=0;setTimeout(()=>$('#loading').hidden=true,300);}
catch(error){console.error(error);$('#loading').innerHTML=`<div class="fatal"><h2>Панораманы ашу мүмкін болмады</h2><p>Интернет байланысын тексеріп, бетті жаңарт.</p><button class="primary" id="retryLoad">Қайта жүктеу</button><button class="secondary" id="readWithout3d">Құқық салаларын оқу</button></div>`;$('#retryLoad').onclick=()=>location.reload();$('#readWithout3d').onclick=()=>showLaws(0)}
